const $=s=>document.querySelector(s);let room='counter',busy=false,sound=false,audio,bubbleTimer,counts={},pourTimer;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const lines={lenny:["Bro. We’re early.","My portfolio is diversified. Three different bad decisions.","I’m not working here. I’m funding phase one.","Once this hits, I’m buying the store. Then closing it."],dale:["It’s 3 a.m., Lenny. We’re at work.","The hot dogs have been rotating since 2009. Explain that.","Nobody puts cameras in a store unless they’re watching you.","That’s not a roadmap. That’s a pizza box."],research:["Every receipt ends with a total. They’re not even hiding it.","The dumpster knows more than the whitepaper."],pizza:["LENNY: That slice was our marketing budget.","DALE: You’ve just diluted the pizza supply."]};
function beep(freq=440,duration=.1){if(!sound)return;audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.start();o.stop(audio.currentTime+duration)}
function say(name,text){window.roomMotion?.react(name);clearTimeout(bubbleTimer);$('#bubble').replaceChildren();const strong=document.createElement('strong');strong.textContent=name.toUpperCase();$('#bubble').append(strong,document.createTextNode(text));$('#bubble').classList.add('on');bubbleTimer=setTimeout(()=>$('#bubble').classList.remove('on'),5000);beep(180,.07)}
document.querySelectorAll('[data-person]').forEach(b=>b.addEventListener('click',()=>{const p=b.dataset.person;const n=counts[p]??0;counts[p]=n+1;say(p==='pizza'?'THE LAST SLICE':p==='research'?'DALE':p,lines[p][n%lines[p].length])}));
const panels={lore:`<span class="eyebrow">EMPLOYEE FILES // DEFINITELY CONFIDENTIAL</span><h1>Two idiots.<br>One last shift.</h1><p>Lenny and Dale launched a coin to escape the night shift. Neither can afford to quit.</p><h2>LENNY — Chief Delusion Officer</h2><p>Overnight cashier. Full-time future millionaire. Calls the convenience store “headquarters” and a blue slushie “liquid assets.” His exit strategy is telling everyone he has an exit strategy.</p><h2>DALE — Head of Research</h2><p>Convinced the hot-dog roller controls the market. Keeps every receipt. Trusts nobody, especially the employee-of-the-month committee.</p><p><b>Minimum wage. Maximum delusion.</b> Every shift is another episode of their terrible escape plan.</p>`,buy:`<span class="eyebrow">REGISTER // CHECKOUT INSTRUCTIONS</span><h1>How to clock in.</h1><p class="note">Concept preview: token network, contract address, and official purchase link have not been announced. Buying is unavailable here.</p><ol><li><b>Wait for the official launch details.</b> The verified network and contract address will appear here.</li><li><b>Prepare a compatible wallet.</b> Once the network is confirmed, use the matching wallet and leave enough native currency for network fees.</li><li><b>Use the official purchase link.</b> Match the full contract address before confirming any swap.</li></ol><p>Contract address: <b>NOT ANNOUNCED</b><br>Purchase link: <b>NOT ANNOUNCED</b></p><p>LENNY: “The register is ready. Corporate is not.”</p>`,roadmap:`<span class="eyebrow">THE STOCKROOM // PROPOSED ROADMAP</span><h1>The escape plan.</h1><p class="note">These are proposed creative milestones, not completed releases or promised dates.</p><h2>01 / CLOCK IN</h2><p>Establish the characters, launch the interactive store, and publish verified token and community information.</p><h2>02 / SPREAD THE STUPIDITY</h2><p>Release character meme packs, a caption maker, and short night-shift episodes.</p><h2>03 / NIGHT SHIFT TAKEOVER</h2><p>Expand the parking lot and stockroom with character reactions, community challenges, and linked scene events.</p><h2>04 / STILL NOT RETIRED</h2><p>Introduce additional rooms and small games based on what the community enjoys. Lenny remains on the schedule.</p>`,community:`<span class="eyebrow">STORE TELEPHONE // CORPORATE HOTLINE</span><h1>Nobody picked up.</h1><p>Official community channels have not been supplied yet. This phone will link to verified accounts when they’re ready.</p><p>DALE: “They’re screening our calls.”</p>`,memes:`<span class="eyebrow">MEME SUPPLIES // HELP YOURSELF</span><h1>Export the stupidity.</h1><p>Pick a character, write a caption, and download a meme.</p><div class="meme"><p>“BRO. WE’RE EARLY.”</p><p>“IT’S 3 A.M. WE’RE AT WORK.”</p></div><label for="caption">YOUR CAPTION</label><input id="caption" maxlength="95" value="MINIMUM WAGE. MAXIMUM DELUSION."><div style="display:flex;gap:10px;margin-top:12px"><button class="action" id="meme-lenny">LENNY</button><button class="action" id="meme-dale">DALE</button></div><canvas id="meme-canvas" width="1000" height="1000"></canvas><button class="action" id="download">DOWNLOAD PNG ↓</button>`};
function openPanel(p){$('#panel-content').innerHTML=panels[p];$('#panel').showModal();beep(580,.07);if(p==='memes')initMemes()}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));$('.close').onclick=()=>$('#panel').close();$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#panel').close()}});
function changeRoom(next){if(next===room||busy)return;busy=true;$('#bubble').classList.remove('on');window.roomMotion?.beforeTravel(next);if(!reduced){$('#warp').classList.add('active');beep(740,.2);setTimeout(()=>beep(1080,.2),170)}setTimeout(()=>{document.querySelectorAll('.room').forEach(el=>el.classList.toggle('hidden',el.id!==next));room=next;window.roomMotion?.enter(next);$('#room-title').textContent=next==='parking'?'THE PARKING LOT':next==='stockroom'?'THE STOCKROOM':'THE COUNTER';document.querySelectorAll('.rooms button').forEach(b=>b.classList.toggle('active',b.dataset.room===next));$('#viewport').scrollLeft=next==='counter'?$('#viewport').scrollWidth*.28:0;},reduced?0:950);setTimeout(()=>{$('#warp').classList.remove('active');busy=false;if(next==='parking')say('LENNY','Corporate meeting. Parking lot.');if(next==='stockroom')say('DALE','Don’t touch the strings. They’re load-bearing.');},reduced?0:1800)}
document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>changeRoom(b.dataset.room)));$('#hints').onclick=()=>{const on=$('#world').classList.toggle('show-hints');$('#hints').setAttribute('aria-pressed',on);$('#hints').textContent=on?'HIDE HOTSPOTS −':'SHOW HOTSPOTS +'};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'SOUND ON':'SOUND OFF';$('#sound').setAttribute('aria-pressed',sound);window.roomMotion?.soundChanged(sound);beep(600,.12)};
$('#viewport').addEventListener('pointermove',e=>{if(reduced||e.pointerType!=='mouse')return;const r=$('#viewport').getBoundingClientRect();$('#world').style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*12+'px');$('#world').style.setProperty('--my',((e.clientY-r.top)/r.height-.5)*7+'px')});$('#viewport').addEventListener('pointerleave',()=>{$('#world').style.setProperty('--mx','0px');$('#world').style.setProperty('--my','0px')});
$('#roller').onclick=()=>{const n=counts.hotdog??0;counts.hotdog=n+1;$('#roller').classList.remove('wiggle');void $('#roller').offsetWidth;$('#roller').classList.add('wiggle');say('DALE',["That one’s been here longer than the manager.","Do not feed it after midnight.","It rotated the other way. You saw that, right?"][n%3])};
function stopPour(){clearTimeout(pourTimer);$('#pour').classList.remove('on')}
$('#slush').addEventListener('pointerdown',e=>{e.currentTarget.setPointerCapture(e.pointerId);$('#pour').classList.add('on');beep(120,.3);pourTimer=setTimeout(()=>{$('#spill').classList.add('on');say('LENNY','Bro. You just increased our liquidity.');},1100)});$('#slush').addEventListener('pointerup',stopPour);$('#slush').addEventListener('pointercancel',stopPour);$('#slush').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#spill').classList.add('on');say('LENNY','Bro. You just increased our liquidity.')}});$('#pan-left').onclick=()=>$('#viewport').scrollBy({left:-250,behavior:reduced?'instant':'smooth'});$('#pan-right').onclick=()=>$('#viewport').scrollBy({left:250,behavior:reduced?'instant':'smooth'});
function initMemes(){let who='lenny';const canvas=$('#meme-canvas'),ctx=canvas.getContext('2d'),img=new Image();function draw(){ctx.fillStyle='#f3e3bb';ctx.fillRect(0,0,1000,1000);ctx.fillStyle='#ef4735';ctx.fillRect(0,0,1000,18);if(img.complete&&img.naturalWidth){const w=who==='lenny'?640:800,h=w*img.height/img.width;ctx.save();if(who==='dale')ctx.filter='url(#clean-alpha)';ctx.drawImage(img,(1000-w)/2,45,w,Math.min(h,780));ctx.restore()}ctx.fillStyle='#151c25';ctx.fillRect(0,790,1000,210);ctx.fillStyle='#f3e3bb';ctx.textAlign='center';ctx.font='bold 45px sans-serif';const words=$('#caption').value.toUpperCase().split(' ');let lines=[],line='';for(const word of words){if(ctx.measureText(line+word).width>900){lines.push(line.trim());line=''}line+=word+' '}lines.push(line.trim());lines.slice(0,3).forEach((s,i)=>ctx.fillText(s,500,855+i*51));ctx.font='18px monospace';ctx.fillStyle='#ef4735';ctx.fillText('LENNY’S LAST SHIFT',500,775)}function choose(p){who=p;img.onload=draw;img.src='assets/'+p+'.png'}$('#caption').oninput=draw;$('#meme-lenny').onclick=()=>choose('lenny');$('#meme-dale').onclick=()=>choose('dale');$('#download').onclick=()=>{const a=document.createElement('a');a.download='lennys-last-shift-'+who+'.png';a.href=canvas.toDataURL('image/png');a.click()};choose('lenny')}
window.addEventListener('load',()=>{if(innerWidth<800)$('#viewport').scrollLeft=$('#viewport').scrollWidth*.28});
